codigo_corregido:
import threading

contador = 0
lock = threading.Lock()

def incrementar():
    global contador
    for _ in range(100000):
        with lock:  # solo un thread entra a la vez
            contador += 1

threads = [threading.Thread(target=incrementar) for _ in range(10)]
for t in threads: t.start()
for t in threads: t.join()

print(f'Contador final: {contador}')  # 1,000,000 exactos

